import orders from './orders.json' with {type: 'json'};

export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order. Optionally include the chronological history of status changes.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The unique identifier of the order.' },
          include_history: { type: 'boolean', description: 'Whether to include the chronological status history.', default: false }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate arguments
  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  if (!('order_id' in args)) {
    throw new Error('Missing required field: order_id');
  }

  const orderId = args.order_id;
  if (typeof orderId !== 'string') {
    throw new Error('order_id must be a string');
  }

  let includeHistory = false;
  if ('include_history' in args) {
    if (typeof args.include_history !== 'boolean') {
      throw new Error('include_history must be a boolean');
    }
    includeHistory = args.include_history;
  }

  const order = orders[orderId];
  if (!order) {
    throw new Error(`Order not found: ${orderId}`);
  }

  const lines = [`Status: ${order.status}`];
  if (includeHistory && Array.isArray(order.history)) {
    lines.push('History:');
    for (const entry of order.history) {
      lines.push(`- ${entry}`);
    }
  }

  return {
    content: [{ type: 'text', text: lines.join('\n') }]
  };
}
